/** The PALMSTORE logo (wordmark and tagline) for PDF reports, receipts and the audit report. Width:height = 1181:220. */
export const REPORT_LOGO = "data:image/png;base64,";
export const REPORT_LOGO_RATIO = 5.368182;

/**
 * Top-left of every PDF: the PALMSTORE logo, then the business name when it isn't simply "Palm Store"
 * (e.g. "Palmbite Social Cafe"), so each business's reports still say whose they are.
 */
export function reportBrand(storeName: string, width = 150, nameSize = 11): unknown[] {
  const own = storeName.trim() && storeName.trim().toLowerCase() !== "palm store";
  return [
    { image: REPORT_LOGO, width, margin: [0, 0, 0, 4] },
    ...(own ? [{ text: storeName, fontSize: nameSize, bold: true, color: "#2B2B2B", margin: [0, 0, 0, 1] }] : []),
  ];
}
